const { useState, useEffect, useRef } = React;

const SHIP = 60;           // 우주선 크기(px)
const TILT_DEAD = 4;       // 기울기 데드존(도) — 이 안이면 정지
const TILT_MAX = 25;       // 이 각도(도)에서 최대 속도
const MOVE_SPEED = 0.55;   // 최대 이동 속도(px/ms)
const FIRE_COOLDOWN = 220; // 연사 간격(ms)
const BULLET_SPEED = 0.9;  // 총알 속도(px/ms)

// 별 배경은 한 번만 만들어 고정 (렌더마다 위치가 바뀌면 별이 튐)
const STARS = [...Array(120)].map(() => ({
  size: Math.max(1, Math.random() * 2.5),
  left: Math.random() * 100,
  top: Math.random() * 100,
  opacity: Math.random() * 0.8 + 0.2,
  glow: Math.random() * 4 + 2,
  dur: Math.random() * 4 + 2,
  delay: Math.random() * 3,
}));

let bestScore = 0; // 세션 동안 유지되는 최고 점수

function App() {
  const [gameOver, setGameOver] = useState(false);
  const [score, setScore] = useState(0);
  const [kills, setKills] = useState(0);
  const [, bump] = useState(0);

  const areaRef = useRef(null);
  const sizeRef = useRef({ w: 1100, h: 620 });          // 게임 영역 실제 크기(창에 맞춰 갱신)
  const posRef = useRef({ x: 0, y: 0, placed: false });
  const tiltRef = useRef({ roll: 0, pitch: 0 });        // IMU 원본 각도(도)
  const smoothRef = useRef({ x: 0, y: 0 });             // 저역통과된 -1~1 입력
  const keyRef = useRef({ x: 0, y: 0, fire: false });   // 키보드 폴백
  const btnRef = useRef(false);                          // MODI 버튼 눌림 상태
  const meteorsRef = useRef([]);
  const bulletsRef = useRef([]);
  const particlesRef = useRef([]);
  const nodeMap = useRef(new Map());
  const resetRef = useRef(() => {});
  const gameRef = useRef({
    over: false, score: 0, kills: 0,
    startAt: 0, diedAt: 0, lastTick: 0,
    lastSpawn: 0, lastFire: 0, lastSound: 0, ledOff: 0,
    nextMilestone: 100, nextId: 0,
  });

  // MODI 입력: IMU 기울기(roll=좌우, pitch=앞뒤) + 버튼(pressed) → 전부 ref에만 저장
  useEffect(() => {
    const offRoll = MODI.onValue('imu', 1, 'roll', (v) => { tiltRef.current.roll = v || 0; }, { pollMs: 30 });
    const offPitch = MODI.onValue('imu', 1, 'pitch', (v) => { tiltRef.current.pitch = v || 0; }, { pollMs: 30 });
    const offBtn = MODI.onValue('button', 1, 'pressed', (v) => { btnRef.current = !!v; }, { pollMs: 30 });
    return () => { offRoll(); offPitch(); offBtn(); };
  }, []);

  // 키보드 폴백: 방향키/WASD 이동, 스페이스·엔터 발사 (하드웨어 없이도 플레이 가능)
  useEffect(() => {
    const down = (e) => {
      if (e.key === 'ArrowLeft' || e.key === 'a') keyRef.current.x = -1;
      else if (e.key === 'ArrowRight' || e.key === 'd') keyRef.current.x = 1;
      else if (e.key === 'ArrowUp' || e.key === 'w') keyRef.current.y = -1;
      else if (e.key === 'ArrowDown' || e.key === 's') keyRef.current.y = 1;
      else if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); keyRef.current.fire = true; }
    };
    const up = (e) => {
      if (['ArrowLeft', 'a', 'ArrowRight', 'd'].includes(e.key)) keyRef.current.x = 0;
      if (['ArrowUp', 'w', 'ArrowDown', 's'].includes(e.key)) keyRef.current.y = 0;
      if (e.key === ' ' || e.key === 'Enter') keyRef.current.fire = false;
    };
    window.addEventListener('keydown', down);
    window.addEventListener('keyup', up);
    return () => { window.removeEventListener('keydown', down); window.removeEventListener('keyup', up); };
  }, []);

  // 게임 영역 크기를 실측해서 창 크기가 바뀌어도 물리 좌표가 따라가게 함
  useEffect(() => {
    const el = areaRef.current;
    if (!el) return;
    const measure = () => {
      const r = el.getBoundingClientRect();
      sizeRef.current = { w: r.width, h: r.height };
      if (!posRef.current.placed) {
        posRef.current = { x: r.width / 2 - SHIP / 2, y: r.height - SHIP * 1.6, placed: true };
      }
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  // 게임 루프
  useEffect(() => {
    let raf;
    let last = performance.now();
    let lastHud = 0;

    const playTone = (freq, dur) => {
      const g = gameRef.current;
      const now = performance.now();
      if (now - g.lastSound > 90) { MODI.speaker(1).playTone(freq, dur); g.lastSound = now; }
    };

    const explode = (cx, cy, count) => {
      for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2 + (Math.random() - 0.5) * 0.6;
        const speed = 3 + Math.random() * 5;
        particlesRef.current.push({
          id: gameRef.current.nextId++,
          x: cx, y: cy,
          vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
          life: 1, decay: 0.04 + Math.random() * 0.03,
        });
      }
      bump((v) => v + 1);
    };

    const doReset = () => {
      const { w, h } = sizeRef.current;
      const t = performance.now();
      posRef.current = { x: w / 2 - SHIP / 2, y: h - SHIP * 1.6, placed: true };
      smoothRef.current = { x: 0, y: 0 };
      meteorsRef.current = [];
      bulletsRef.current = [];
      particlesRef.current = [];
      gameRef.current = {
        over: false, score: 0, kills: 0,
        startAt: t, diedAt: 0, lastTick: t,
        lastSpawn: t, lastFire: 0, lastSound: 0, ledOff: 0,
        nextMilestone: 100, nextId: 0,
      };
      setGameOver(false); setScore(0); setKills(0);
      bump((v) => v + 1);
      MODI.led(1).setColor(0, 0, 0);
      MODI.speaker(1).playTone(523, 120);
    };
    resetRef.current = doReset;

    const t0 = performance.now();
    gameRef.current.startAt = t0;
    gameRef.current.lastTick = t0;
    gameRef.current.lastSpawn = t0;
    MODI.led(1).setColor(0, 0, 0); // LED는 평소엔 꺼두고 이벤트 때만 반짝임

    const loop = (now) => {
      const dt = Math.min(50, now - last); // 프레임이 밀려도 순간이동 방지
      last = now;
      const g = gameRef.current;
      const p = posRef.current;
      const { w, h } = sizeRef.current;
      const ms = meteorsRef.current;
      const bs = bulletsRef.current;
      const ps = particlesRef.current;
      const firing = btnRef.current || keyRef.current.fire;

      if (!g.over) {
        // IMU 기울기 → -1~1 입력: 데드존으로 미세 떨림 무시, 저역통과로 부드럽게
        // 이 모듈 장착 방향에선 pitch가 좌우(오른쪽 +), roll이 앞뒤(앞쪽 +)를 잰다
        // (좌우가 반대면 pitch 부호를, 위아래가 반대면 roll 부호를 뒤집으세요)
        const t = tiltRef.current;
        const rawX = Math.abs(t.pitch) < TILT_DEAD ? 0 : Math.max(-1, Math.min(1, t.pitch / TILT_MAX));
        const rawY = Math.abs(t.roll) < TILT_DEAD ? 0 : Math.max(-1, Math.min(1, -t.roll / TILT_MAX));
        const s = smoothRef.current;
        s.x += (Math.max(-1, Math.min(1, rawX + keyRef.current.x)) - s.x) * 0.22;
        s.y += (Math.max(-1, Math.min(1, rawY + keyRef.current.y)) - s.y) * 0.22;

        // 속도형 이동: 기울인 방향·세기만큼 계속 이동, 놓으면 그 자리에 정지
        p.x = Math.max(0, Math.min(w - SHIP, p.x + s.x * MOVE_SPEED * dt));
        p.y = Math.max(0, Math.min(h - SHIP, p.y + s.y * MOVE_SPEED * dt));

        // 발사: 버튼(또는 스페이스)을 누르고 있으면 쿨다운 간격으로 연사
        if (firing && now - g.lastFire > FIRE_COOLDOWN) {
          bs.push({ id: g.nextId++, x: p.x + SHIP / 2 - 5, y: p.y - 10 });
          g.lastFire = now;
          playTone(880, 40);
          bump((v) => v + 1);
        }

        // 난이도 상승: 시간이 갈수록 운석이 더 자주, 더 빠르게 떨어짐
        const elapsed = now - g.startAt;
        const spawnGap = Math.max(420, 1200 - elapsed * 0.02);
        const speedUp = 1 + Math.min(1.4, elapsed / 45000);
        if (now - g.lastSpawn > spawnGap) {
          const size = 42 + Math.random() * 34;
          ms.push({
            id: g.nextId++,
            x: Math.random() * Math.max(1, w - size),
            y: -size, size,
            speed: (0.12 + Math.random() * 0.15) * speedUp,
            spin: (Math.random() - 0.5) * 0.15,
          });
          g.lastSpawn = now;
          bump((v) => v + 1);
        }

        // 총알 이동 + 운석 명중 판정 (명중 시 +15점, 폭발 파티클)
        for (let i = bs.length - 1; i >= 0; i--) {
          const b = bs[i];
          b.y -= BULLET_SPEED * dt;
          let hit = false;
          for (let k = ms.length - 1; k >= 0; k--) {
            const m = ms[k];
            if (b.x < m.x + m.size && b.x + 10 > m.x && b.y < m.y + m.size && b.y + 24 > m.y) {
              ms.splice(k, 1);
              g.kills += 1;
              g.score += 15;
              setKills(g.kills);
              explode(m.x + m.size / 2, m.y + m.size / 2, 10);
              playTone(196, 120);
              MODI.led(1).setColor(0, 255, 0); g.ledOff = now + 500; // 격추: 초록 0.5초
              hit = true;
              break;
            }
          }
          if (hit || b.y < -30) { bs.splice(i, 1); bump((v) => v + 1); }
        }

        // 운석 낙하 + 우주선 충돌 (판정 상자를 8px 줄여 억울한 죽음 방지)
        const PAD = 8;
        for (let i = ms.length - 1; i >= 0; i--) {
          const m = ms[i];
          m.y += m.speed * dt;
          if (m.x < p.x + SHIP - PAD && m.x + m.size > p.x + PAD &&
              m.y < p.y + SHIP - PAD && m.y + m.size > p.y + PAD) {
            g.over = true;
            g.diedAt = now;
            bestScore = Math.max(bestScore, g.score);
            setGameOver(true);
            setScore(g.score);
            MODI.led(1).setColor(255, 0, 0); g.ledOff = now + 500; // 피격: 빨강 0.5초
            MODI.speaker(1).playTone(80, 400);
            explode(p.x + SHIP / 2, p.y + SHIP / 2, 16);
          }
          if (m.y > h) { ms.splice(i, 1); bump((v) => v + 1); }
        }

        // 파티클
        for (let i = ps.length - 1; i >= 0; i--) {
          const pt = ps[i];
          pt.x += pt.vx;
          pt.y += pt.vy;
          pt.vy += 0.2;
          pt.life -= pt.decay;
          if (pt.life <= 0) { ps.splice(i, 1); bump((v) => v + 1); }
        }

        // 점수: 생존 100ms당 1점, 100점 고비마다 축하음. HUD 갱신은 150ms throttle
        if (now - g.lastTick >= 100) {
          g.score += Math.floor((now - g.lastTick) / 100);
          g.lastTick = now;
          if (g.score >= g.nextMilestone) { playTone(1047, 100); g.nextMilestone += 100; }
        }
        if (now - lastHud >= 150) { setScore(g.score); lastHud = now; }
      } else if (firing && now - g.diedAt > 800) {
        // 게임오버 후 0.8초가 지나면 MODI 버튼(또는 스페이스)으로 바로 재시작
        doReset();
      }

      // LED는 이벤트 플래시 전용: 켜진 지 0.5초가 지나면 끈다 (게임오버 중에도 동작)
      if (g.ledOff && now >= g.ledOff) { MODI.led(1).setColor(0, 0, 0); g.ledOff = 0; }

      // DOM 직접 갱신 (리렌더 없음): 우주선은 기울인 방향으로 살짝 기울어짐
      const shipEl = nodeMap.current.get('ship');
      if (shipEl) shipEl.style.transform = `translate3d(${p.x}px,${p.y}px,0) rotate(${smoothRef.current.x * 16}deg)`;

      const dotEl = nodeMap.current.get('dot');
      if (dotEl) dotEl.style.transform = `translate3d(${smoothRef.current.x * 20}px,${smoothRef.current.y * 20}px,0)`;

      for (const m of ms) {
        const el = nodeMap.current.get(`m${m.id}`);
        if (el) el.style.transform = `translate3d(${m.x}px,${m.y}px,0) rotate(${(now * m.spin) % 360}deg)`;
      }
      for (const b of bs) {
        const el = nodeMap.current.get(`b${b.id}`);
        if (el) el.style.transform = `translate3d(${b.x}px,${b.y}px,0)`;
      }
      for (const pt of ps) {
        const el = nodeMap.current.get(`p${pt.id}`);
        if (el) {
          el.style.transform = `translate3d(${pt.x}px,${pt.y}px,0)`;
          el.style.opacity = pt.life;
        }
      }

      raf = requestAnimationFrame(loop);
    };

    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);

  const node = (id) => (el) => {
    if (el) nodeMap.current.set(id, el);
    else nodeMap.current.delete(id);
  };

  return (
    <div className="h-screen w-screen overflow-hidden flex flex-col" style={{ background: 'radial-gradient(ellipse at 50% 100%, #667eea 0%, #764ba2 25%, #1a1a2e 100%)' }}>
      {/* 별 배경 (모듈 로드 시 한 번만 생성된 STARS 사용) */}
      <div className="absolute inset-0 z-0 pointer-events-none">
        {STARS.map((st, i) => (
          <div
            key={i}
            className="absolute rounded-full bg-white"
            style={{
              width: st.size + 'px', height: st.size + 'px',
              left: st.left + '%', top: st.top + '%',
              opacity: st.opacity,
              boxShadow: `0 0 ${st.glow}px rgba(255,255,255,0.8)`,
              animation: `twinkle ${st.dur}s infinite ${st.delay}s`,
            }}
          />
        ))}
        <style>{`
          @keyframes twinkle { 0%,100% { opacity: 0.2; } 50% { opacity: 0.9; } }
          @keyframes flame { 0%,100% { transform: translateX(-50%) scaleY(1); opacity: 0.9; } 50% { transform: translateX(-50%) scaleY(1.5); opacity: 0.6; } }
        `}</style>
      </div>

      {/* 상단 HUD: 제목 · 점수 · 최고점수 · 격추 수 · 기울기 인디케이터 */}
      <div className="relative z-10 flex items-center justify-between gap-6 px-8 py-4">
        <h1 className="text-4xl font-black whitespace-nowrap" style={{ color: '#00d4ff', textShadow: '0 0 16px #00d4ff' }}>
          🚀 SPACE SHOOTER
        </h1>
        <div className="flex items-center gap-8">
          <p className="text-3xl font-black" style={{ color: '#ffdd44', textShadow: '0 0 10px #ffaa00' }}>📊 {score}</p>
          <p className="text-2xl font-bold text-white/90">🏆 {Math.max(bestScore, score)}</p>
          <p className="text-2xl font-bold" style={{ color: '#ff8866' }}>💥 {kills}</p>
          {/* 기울기 인디케이터: 지금 IMU가 어느 방향으로 얼마나 기울었는지 표시 */}
          <div className="relative w-14 h-14 rounded-xl border-2 border-cyan-400/60 bg-black/30">
            <div className="absolute left-1/2 top-0 bottom-0 w-px bg-cyan-400/30" />
            <div className="absolute top-1/2 left-0 right-0 h-px bg-cyan-400/30" />
            <div ref={node('dot')} className="absolute rounded-full" style={{ left: 23, top: 23, width: 10, height: 10, background: '#00d4ff', boxShadow: '0 0 8px #00d4ff', willChange: 'transform' }} />
          </div>
        </div>
      </div>

      {/* 게임 영역: 창 크기에 맞춰 늘어나고, 실제 크기는 ResizeObserver로 측정 */}
      <div
        ref={areaRef}
        className="relative flex-1 min-h-0 mx-6 mb-5 rounded-3xl overflow-hidden border-4 z-10"
        style={{
          borderColor: '#00d4ff',
          background: 'linear-gradient(135deg, #0f3460 0%, #16213e 50%, #1a1a2e 100%)',
          boxShadow: '0 0 60px rgba(0, 212, 255, 0.4), inset 0 0 60px rgba(0, 100, 200, 0.1)',
        }}
      >
        {/* 우주선 (엔진 불꽃 포함, 위를 향하도록 회전) */}
        <div ref={node('ship')} className="absolute" style={{ left: 0, top: 0, width: SHIP, height: SHIP, willChange: 'transform' }}>
          <div style={{ fontSize: SHIP - 8, lineHeight: 1, transform: 'rotate(-45deg)' }}>🚀</div>
          <div className="absolute text-2xl" style={{ left: '50%', bottom: -14, transform: 'translateX(-50%)', animation: 'flame 0.3s infinite' }}>🔥</div>
        </div>

        {/* 총알들 */}
        {bulletsRef.current.map((b) => (
          <div key={b.id} ref={node(`b${b.id}`)} className="absolute rounded-full" style={{ left: 0, top: 0, width: 10, height: 24, background: 'linear-gradient(180deg, #ffffff, #00d4ff)', boxShadow: '0 0 12px #00d4ff', willChange: 'transform' }} />
        ))}

        {/* 운석들 (크기 랜덤) */}
        {meteorsRef.current.map((m) => (
          <div key={m.id} ref={node(`m${m.id}`)} className="absolute drop-shadow-lg" style={{ left: 0, top: 0, fontSize: m.size - 6, lineHeight: 1, willChange: 'transform' }}>🪨</div>
        ))}

        {/* 파티클들 */}
        {particlesRef.current.map((pt) => (
          <div key={pt.id} ref={node(`p${pt.id}`)} className="absolute text-3xl" style={{ left: 0, top: 0, willChange: 'transform', opacity: pt.life }}>✨</div>
        ))}

        {/* 조작 안내 */}
        <p className="absolute bottom-3 left-1/2 -translate-x-1/2 text-white/50 text-sm whitespace-nowrap z-10">
          🎮 IMU를 기울여 사방으로 이동 · 버튼으로 발사 &nbsp;|&nbsp; ⌨️ 방향키/WASD + 스페이스
        </p>

        {/* 게임오버 화면 */}
        {gameOver && (
          <div className="absolute inset-0 bg-black/85 backdrop-blur-sm flex flex-col items-center justify-center gap-6 z-50">
            <div className="text-8xl animate-bounce">💥</div>
            <h2 className="text-6xl font-black" style={{ color: '#ff4444', textShadow: '0 0 20px #ff0000' }}>GAME OVER</h2>
            <div className="flex gap-10 text-center">
              <div>
                <p className="text-lg text-white/60 font-bold">SCORE</p>
                <p className="text-5xl font-black" style={{ color: '#ffdd44' }}>{score}</p>
              </div>
              <div>
                <p className="text-lg text-white/60 font-bold">BEST</p>
                <p className="text-5xl font-black" style={{ color: '#00d4ff' }}>{bestScore}</p>
              </div>
              <div>
                <p className="text-lg text-white/60 font-bold">HITS</p>
                <p className="text-5xl font-black" style={{ color: '#ff8866' }}>{kills}</p>
              </div>
            </div>
            <button
              className="px-12 py-5 text-2xl font-black rounded-2xl transition-all active:scale-95"
              style={{ background: 'linear-gradient(135deg, #00d4ff, #0099ff)', color: 'white', textShadow: '0 2px 4px rgba(0,0,0,0.3)' }}
              onClick={() => resetRef.current()}
            >
              RESTART
            </button>
            <p className="text-white/50 text-base">MODI 버튼이나 스페이스를 눌러도 다시 시작돼요</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
